    for (var i = 0; i < rows.length; i++) {
      if (rows[i].type === "same") continue
      for (var d = -ctx; d <= ctx; d++) if (rows[i + d]) mark[i + d] = true
    }
    for (var m = 0; m < rows.length; m++) if (mark[m]) keep.push(m)
